using Licitaciones.Application.Aprobaciones;
namespace Licitaciones.Api.Endpoints.Aprobaciones;
public sealed record NivelRequest(string Responsable, decimal MontoMinimoCrc, decimal? MontoMaximoCrc);
public static class NivelAprobacionEndpoints
{ public static IEndpointRouteBuilder MapNivelesAprobacion(this IEndpointRouteBuilder app) { var g = app.MapGroup("/api/v1/niveles-aprobacion"); g.MapPost("", async (NivelRequest r, NivelAprobacionService s, CancellationToken c) => Results.Created("", await s.CrearAsync(r.Responsable, r.MontoMinimoCrc, r.MontoMaximoCrc, c))); g.MapGet("", async (NivelAprobacionService s, CancellationToken c) => Results.Ok(await s.ListarAsync(c))); g.MapGet("/{id:guid}", async (Guid id, NivelAprobacionService s, CancellationToken c) => Results.Ok(await s.ObtenerAsync(id, c))); g.MapPut("/{id:guid}", async (Guid id, NivelRequest r, NivelAprobacionService s, CancellationToken c) => { await s.EditarAsync(id, r.Responsable, r.MontoMinimoCrc, r.MontoMaximoCrc, c); return Results.NoContent(); }); g.MapDelete("/{id:guid}", async (Guid id, NivelAprobacionService s, CancellationToken c) => { await s.EliminarAsync(id, c); return Results.NoContent(); }); g.MapGet("/determinar/{monto:decimal}", async (decimal monto, NivelAprobacionService s, CancellationToken c) => Results.Ok(await s.DeterminarAsync(monto, c))); return app; } }
